CREATE TABLE IF NOT EXISTS customers (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, email VARCHAR(220) UNIQUE NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT, price NUMERIC(19,4) NOT NULL, is_available BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE, customer_id BIGINT NOT NULL REFERENCES customers(id), status VARCHAR(24) NOT NULL, total NUMERIC(19,4) NOT NULL, shipping_address TEXT, placed_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price NUMERIC(19,4) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, amount NUMERIC(19,4) NOT NULL, method VARCHAR(24) NOT NULL, status VARCHAR(24) NOT NULL, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS migration_runs (id UUID PRIMARY KEY, state VARCHAR(40) NOT NULL, snapshot_boundary BIGINT NOT NULL DEFAULT 0, last_applied_change BIGINT NOT NULL DEFAULT 0, active_database VARCHAR(20) NOT NULL DEFAULT 'sqlserver', writes_frozen BOOLEAN NOT NULL DEFAULT FALSE, config JSONB NOT NULL DEFAULT '{}', resume_stage VARCHAR(40), started_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS migration_checkpoints (run_id UUID NOT NULL REFERENCES migration_runs(id) ON DELETE CASCADE, table_name VARCHAR(80) NOT NULL, last_processed_id BIGINT NOT NULL DEFAULT -1, rows_processed BIGINT NOT NULL DEFAULT 0, batch_number INTEGER NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'pending', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(run_id, table_name));
CREATE TABLE IF NOT EXISTS applied_changes (change_id BIGINT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lab_events (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, category VARCHAR(30) NOT NULL, level VARCHAR(10) NOT NULL, message TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lab_settings (key TEXT PRIMARY KEY, value JSONB NOT NULL);
INSERT INTO lab_settings(key,value) VALUES ('active_database','"sqlserver"'),('writes_frozen','false'),('postgres_only_writes','0') ON CONFLICT DO NOTHING;
